import AppKit
import CoreText
import PDFKit

// Markup PDFKit can't draw itself (polygons, clouds, stamps, carets, paper clips, measurements). PDFKit records what
// `draw(with:in:)` paints as the annotation's appearance stream when it writes the file, so other readers show the same
// thing (features #76: "appearance streams generated by Own for fidelity in other readers").

extension PDFAnnotationKey {
    /// MarkupKit's id for an annotation while the document is open; written as /NM and removed when the file is saved
    /// (PDFKit drops /NM itself, see `AnnotationLedger`).
    static let superPDFID = PDFAnnotationKey(rawValue: "/SuperPDFID")
    static let vertices = PDFAnnotationKey(rawValue: "/Vertices")
    static let intent = PDFAnnotationKey(rawValue: "/IT")
    static let measure = PDFAnnotationKey(rawValue: "/Measure")
    static let borderEffect = PDFAnnotationKey(rawValue: "/BE")
    static let state = PDFAnnotationKey(rawValue: "/State")
    static let stateModel = PDFAnnotationKey(rawValue: "/StateModel")
    static let creationDate = PDFAnnotationKey(rawValue: "/CreationDate")
    static let subject = PDFAnnotationKey(rawValue: "/Subj")
    static let caption = PDFAnnotationKey(rawValue: "/Cap")
    static let opacity = PDFAnnotationKey(rawValue: "/CA")
}

extension PDFAnnotationSubtype {
    static let polygon = PDFAnnotationSubtype(rawValue: "Polygon")
    static let polyLine = PDFAnnotationSubtype(rawValue: "PolyLine")
    static let caret = PDFAnnotationSubtype(rawValue: "Caret")
    static let fileAttachment = PDFAnnotationSubtype(rawValue: "FileAttachment")
    static let sound = PDFAnnotationSubtype(rawValue: "Sound")
}

/// What a drawn annotation paints, in page space.
enum Drawing {
    /// Star, polygon, speech bubble (closed) or a polyline, through these vertices.
    case vertices([CGPoint], closed: Bool)
    case roundedRect(radius: CGFloat)
    /// Acrobat's cloudy border around the annotation's rectangle.
    case cloud
    /// A standard stamp: the name in capitals and, under it, who and when.
    case stamp(StandardStamp, detail: String)
    /// A picture stamp (PNG, JPEG, TIFF or a one-page PDF).
    case image(Data)
    /// The proofreading caret (features #78).
    case caret
    /// The paper clip of a file attachment, or the speaker of a voice note (features #79).
    case paperclip
    case speaker
    /// A measurement: the line or outline and its value (features #15).
    case measurement([CGPoint], closed: Bool, label: String)
    /// Preview's loupe: the page under the circle, magnified this many times, drawn live.
    case loupe(CGFloat)
    /// The appearance an annotation already had, as a one-page PDF: what a moved or resized annotation that PDFKit
    /// can't redraw keeps showing.
    case appearance(Data, originalBounds: CGRect)
}

final class DrawnAnnotation: PDFAnnotation {
    var drawing: Drawing = .caret

    convenience init(bounds: CGRect, type: PDFAnnotationSubtype, drawing: Drawing) {
        self.init(bounds: bounds, forType: type, withProperties: nil)
        self.drawing = drawing
    }

    override func copy(with zone: NSZone? = nil) -> Any {
        let copy = super.copy(with: zone)
        (copy as? DrawnAnnotation)?.drawing = drawing
        return copy
    }

    /// Moves the drawing with its annotation.
    func translate(by dx: CGFloat, _ dy: CGFloat) {
        let shift = CGAffineTransform(translationX: dx, y: dy)
        switch drawing {
        case .vertices(let points, let closed): drawing = .vertices(points.map { $0.applying(shift) }, closed: closed)
        case .measurement(let points, let closed, let label): drawing = .measurement(points.map { $0.applying(shift) }, closed: closed, label: label)
        default: break
        }
        bounds = bounds.offsetBy(dx: dx, dy: dy)
    }

    private var strokeColor: CGColor { (color.alphaComponent > 0 ? color : NSColor.black).cgColor }
    private var lineWidth: CGFloat { max(border?.lineWidth ?? 1, 0.5) }

    override func draw(with box: PDFDisplayBox, in context: CGContext) {
        context.saveGState()
        defer { context.restoreGState() }
        context.setLineJoin(.round)
        context.setLineCap(.round)
        context.setStrokeColor(strokeColor)
        context.setLineWidth(lineWidth)
        if border?.style == .dashed { context.setLineDash(phase: 0, lengths: [lineWidth * 3, lineWidth * 2]) }
        let fill = interiorColor.map { $0.alphaComponent > 0 ? $0.cgColor : nil } ?? nil
        switch drawing {
        case .vertices(let points, let closed):
            stroke(Geometry.path(through: points, closed: closed), fill: closed ? fill : nil, in: context)
        case .roundedRect(let radius):
            let rect = bounds.insetBy(dx: lineWidth / 2, dy: lineWidth / 2)
            stroke(CGPath(roundedRect: rect, cornerWidth: min(radius, rect.width / 2), cornerHeight: min(radius, rect.height / 2), transform: nil),
                   fill: fill, in: context)
        case .cloud:
            let radius = max(4, lineWidth * 3)
            stroke(Geometry.cloud(in: bounds.insetBy(dx: radius + lineWidth, dy: radius + lineWidth), radius: radius), fill: fill, in: context)
        case .stamp(let stamp, let detail):
            Self.drawStamp(stamp.title.uppercased(), detail: detail, color: stamp.color.cgColor, in: bounds, context: context)
        case .image(let data):
            Self.drawImage(data, in: bounds, context: context)
        case .caret:
            let path = CGMutablePath()
            path.move(to: CGPoint(x: bounds.minX, y: bounds.minY))
            path.addQuadCurve(to: CGPoint(x: bounds.midX, y: bounds.maxY), control: CGPoint(x: bounds.midX - bounds.width * 0.1, y: bounds.minY + bounds.height * 0.3))
            path.addQuadCurve(to: CGPoint(x: bounds.maxX, y: bounds.minY), control: CGPoint(x: bounds.midX + bounds.width * 0.1, y: bounds.minY + bounds.height * 0.3))
            path.closeSubpath()
            context.setFillColor(strokeColor)
            context.addPath(path)
            context.fillPath()
        case .paperclip:
            Self.drawPaperclip(in: bounds, color: strokeColor, context: context)
        case .speaker:
            Self.drawSpeaker(in: bounds, color: strokeColor, context: context)
        case .measurement(let points, let closed, let label):
            context.setLineDash(phase: 0, lengths: [])
            stroke(Geometry.path(through: points, closed: closed), fill: closed ? fill : nil, in: context)
            if !closed, points.count == 2 { Self.drawTicks(points[0], points[1], width: lineWidth, in: context) }
            Self.drawLabel(label, near: points, closed: closed, color: strokeColor, in: context)
        case .loupe(let magnification):
            let circle = bounds.insetBy(dx: lineWidth, dy: lineWidth)
            if let pageRef = page?.pageRef {
                context.saveGState()
                context.addEllipse(in: circle)
                context.clip()
                context.setFillColor(.white)
                context.fill(circle)
                context.translateBy(x: circle.midX, y: circle.midY)
                context.scaleBy(x: magnification, y: magnification)
                context.translateBy(x: -circle.midX, y: -circle.midY)
                context.drawPDFPage(pageRef)   // the page's own content, without its annotations (and this loupe)
                context.restoreGState()
            }
            context.addEllipse(in: circle)
            context.strokePath()
        case .appearance(let data, let original):
            guard let provider = CGDataProvider(data: data as CFData), let pdf = CGPDFDocument(provider), let page = pdf.page(at: 1) else { return }
            context.translateBy(x: bounds.minX, y: bounds.minY)
            context.scaleBy(x: original.width > 0 ? bounds.width / original.width : 1, y: original.height > 0 ? bounds.height / original.height : 1)
            context.drawPDFPage(page)
        }
    }

    private func stroke(_ path: CGPath, fill: CGColor?, in context: CGContext) {
        if let fill {
            context.setFillColor(fill)
            context.addPath(path)
            context.fillPath()
        }
        context.addPath(path)
        context.strokePath()
    }

    // MARK: Pictures

    static func drawStamp(_ title: String, detail: String, color: CGColor, in rect: CGRect, context: CGContext) {
        let frame = rect.insetBy(dx: 2, dy: 2)
        let radius = min(frame.height * 0.18, 10)
        context.setStrokeColor(color)
        context.setLineWidth(max(1.5, frame.height * 0.05))
        context.addPath(CGPath(roundedRect: frame, cornerWidth: radius, cornerHeight: radius, transform: nil))
        context.strokePath()
        let titleHeight = detail.isEmpty ? frame.height * 0.62 : frame.height * 0.48
        let titleFont = fitted("Helvetica-Bold", title, width: frame.width * 0.88, height: titleHeight)
        let nsColor = NSColor(cgColor: color) ?? .black
        let titleLine = line(title, font: titleFont, color: nsColor)
        let titleWidth = CTLineGetTypographicBounds(titleLine, nil, nil, nil)
        let titleY = detail.isEmpty ? frame.midY - titleFont.capHeight / 2 : frame.minY + frame.height * 0.48
        context.textPosition = CGPoint(x: frame.midX - titleWidth / 2, y: titleY)
        CTLineDraw(titleLine, context)
        guard !detail.isEmpty else { return }
        let detailFont = fitted("Helvetica", detail, width: frame.width * 0.88, height: frame.height * 0.2)
        let detailLine = line(detail, font: detailFont, color: nsColor)
        let detailWidth = CTLineGetTypographicBounds(detailLine, nil, nil, nil)
        context.textPosition = CGPoint(x: frame.midX - detailWidth / 2, y: frame.minY + frame.height * 0.18)
        CTLineDraw(detailLine, context)
    }

    static func drawImage(_ data: Data, in rect: CGRect, context: CGContext) {
        if data.starts(with: Data("%PDF".utf8)), let provider = CGDataProvider(data: data as CFData), let pdf = CGPDFDocument(provider),
           let page = pdf.page(at: 1) {
            let media = page.getBoxRect(.cropBox)
            let scale = min(rect.width / max(media.width, 1), rect.height / max(media.height, 1))
            context.translateBy(x: rect.midX - media.width * scale / 2, y: rect.midY - media.height * scale / 2)
            context.scaleBy(x: scale, y: scale)
            context.translateBy(x: -media.minX, y: -media.minY)
            context.drawPDFPage(page)
            return
        }
        guard let source = CGImageSourceCreateWithData(data as CFData, nil), let image = CGImageSourceCreateImageAtIndex(source, 0, nil) else { return }
        let size = CGSize(width: image.width, height: image.height)
        let scale = min(rect.width / max(size.width, 1), rect.height / max(size.height, 1))
        let fit = CGRect(x: rect.midX - size.width * scale / 2, y: rect.midY - size.height * scale / 2, width: size.width * scale, height: size.height * scale)
        context.interpolationQuality = .high
        context.draw(image, in: fit)
    }

    static func drawPaperclip(in rect: CGRect, color: CGColor, context: CGContext) {
        let w = rect.width, h = rect.height
        let x = rect.minX, y = rect.minY
        let path = CGMutablePath()
        // An outer loop, then the inner loop back down: a paper clip standing up.
        path.move(to: CGPoint(x: x + w * 0.62, y: y + h * 0.30))
        path.addLine(to: CGPoint(x: x + w * 0.62, y: y + h * 0.80))
        path.addArc(center: CGPoint(x: x + w * 0.45, y: y + h * 0.80), radius: w * 0.17, startAngle: 0, endAngle: .pi, clockwise: false)
        path.addLine(to: CGPoint(x: x + w * 0.28, y: y + h * 0.22))
        path.addArc(center: CGPoint(x: x + w * 0.50, y: y + h * 0.22), radius: w * 0.22, startAngle: .pi, endAngle: 0, clockwise: false)
        path.addLine(to: CGPoint(x: x + w * 0.72, y: y + h * 0.72))
        context.setStrokeColor(color)
        context.setLineWidth(max(1, w * 0.09))
        context.setLineDash(phase: 0, lengths: [])
        context.addPath(path)
        context.strokePath()
    }

    static func drawSpeaker(in rect: CGRect, color: CGColor, context: CGContext) {
        let w = rect.width, h = rect.height, x = rect.minX, y = rect.minY
        let body = CGMutablePath()
        body.addLines(between: [CGPoint(x: x + w * 0.1, y: y + h * 0.38), CGPoint(x: x + w * 0.3, y: y + h * 0.38),
                                CGPoint(x: x + w * 0.55, y: y + h * 0.15), CGPoint(x: x + w * 0.55, y: y + h * 0.85),
                                CGPoint(x: x + w * 0.3, y: y + h * 0.62), CGPoint(x: x + w * 0.1, y: y + h * 0.62)])
        body.closeSubpath()
        context.setFillColor(color)
        context.addPath(body)
        context.fillPath()
        context.setStrokeColor(color)
        context.setLineWidth(max(1, w * 0.07))
        context.setLineDash(phase: 0, lengths: [])
        for r in [0.18, 0.32] {
            context.addArc(center: CGPoint(x: x + w * 0.55, y: y + h * 0.5), radius: w * r, startAngle: -.pi / 4, endAngle: .pi / 4, clockwise: false)
            context.strokePath()
        }
    }

    static func drawTicks(_ a: CGPoint, _ b: CGPoint, width: CGFloat, in context: CGContext) {
        let angle = atan2(b.y - a.y, b.x - a.x) + .pi / 2
        let half = max(4, width * 3)
        for p in [a, b] {
            context.move(to: CGPoint(x: p.x - cos(angle) * half, y: p.y - sin(angle) * half))
            context.addLine(to: CGPoint(x: p.x + cos(angle) * half, y: p.y + sin(angle) * half))
        }
        context.strokePath()
    }

    /// The value on a white plate: over the middle of a line, or at the centre of an outline.
    static func drawLabel(_ label: String, near points: [CGPoint], closed: Bool, color: CGColor, in context: CGContext) {
        guard !label.isEmpty, !points.isEmpty else { return }
        let anchor: CGPoint
        if closed || points.count > 2 {
            let box = Geometry.bounds(of: points)
            anchor = CGPoint(x: box.midX, y: box.midY)
        } else {
            anchor = CGPoint(x: (points[0].x + points[1].x) / 2, y: (points[0].y + points[1].y) / 2)
        }
        let font = NSFont(name: "Helvetica", size: 10) ?? .systemFont(ofSize: 10)
        let ctLine = line(label, font: font, color: NSColor(cgColor: color) ?? .black)
        let width = CTLineGetTypographicBounds(ctLine, nil, nil, nil)
        let plate = CGRect(x: anchor.x - width / 2 - 3, y: anchor.y - 7, width: width + 6, height: 14)
        context.setFillColor(CGColor(gray: 1, alpha: 0.9))
        context.fill(plate)
        context.textPosition = CGPoint(x: plate.minX + 3, y: plate.minY + 3.5)
        CTLineDraw(ctLine, context)
    }

    static func line(_ text: String, font: NSFont, color: NSColor) -> CTLine {
        CTLineCreateWithAttributedString(NSAttributedString(string: text, attributes: [.font: font, .foregroundColor: color]))
    }

    /// The largest size of `name` up to `height` at which `text` fits `width`.
    static func fitted(_ name: String, _ text: String, width: CGFloat, height: CGFloat) -> NSFont {
        var size = max(4, height)
        while size > 4 {
            let font = NSFont(name: name, size: size) ?? .boldSystemFont(ofSize: size)
            if CTLineGetTypographicBounds(line(text, font: font, color: .black), nil, nil, nil) <= width { return font }
            size -= 0.5
        }
        return NSFont(name: name, size: 4) ?? .systemFont(ofSize: 4)
    }
}
